catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
   var usersysid = g_form.getValue('studnet_name');

//清除选项肢
var arr =g_form.getField("selectboxtest").choices;
var len = g_form.getField("selectboxtest").choices.length;
if(len>1) arr.splice(1, len);

   var globalInvAjax = new GlideAjax('GlideAjax_demo');
	globalInvAjax.addParam('sysparm_name','getStudentObjBySysID');
	globalInvAjax.addParam('sysparm_sysid',usersysid);

	globalInvAjax.getXML(getServiceDetails);

	function getServiceDetails(response){
		var answer = response.responseXML.documentElement.getAttribute("answer");
		var jsonData = JSON.parse(answer);	
		g_form.setValue('student_phone',jsonData.phone);
		g_form.setValue('student_email',jsonData.email);
	}
}
